/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import {
  loadFont as loadInter,
  loadFont as loadSans,
} from "@remotion/google-fonts/Inter";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  Sequence,
  type SequenceControls,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

interface InputStyleContext {
  idleBorder: string;
  hoverBorder: string;
  activeBorder: string;
  invalidBorder: string;
  ring: string;
  invalidRing: string;
  background: string;
  hoverBackground: string;
  foreground: string;
  mutedForeground: string;
}

function inputStyleContext(theme: KitTheme): InputStyleContext {
  return {
    idleBorder: theme.input,
    hoverBorder: mixOklch(theme.input, theme.foreground, 0.18),
    activeBorder: theme.ring,
    invalidBorder: theme.destructive,
    ring: mixOklch(theme.background, theme.ring, 0.5),
    invalidRing: mixOklch(theme.background, theme.destructive, 0.4),
    background: theme.background,
    hoverBackground: mixOklch(theme.background, theme.muted, 0.4),
    foreground: theme.foreground,
    mutedForeground: theme.mutedForeground,
  };
}

// Loaded through @remotion/google-fonts, never a CSS variable — a Remotion
// bundle has none of the app's CSS, so a `var(--font-…)` gets you the right face
// in the Player and a fallback in the mp4 (design-system rule 4).
const { fontFamily: SANS } = loadSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

// --- The stage -------------------------------------------------------------
//
// The reference recording is 890×486, and every ratio below was read off its
// frames, so there is no second conversion to get wrong. `stageScale` fits this
// rectangle into whatever composition the component is given.

const REF_W = 890;
const REF_H = 486;
/** How far past the stage the backdrop is painted, so a cut never frames off it. */
const BLEED = 1.4;
const OX = (REF_W * (BLEED - 1)) / 2;
const OY = (REF_H * (BLEED - 1)) / 2;

// --- Measured proportions --------------------------------------------------
//
// Everything the layout needs is either a fixed inset (a padding, which should
// not change when the type does) or a **ratio of a font size** (a type metric,
// which must). Feeding the defaults through `layoutFor` reproduces the
// recording's own geometry to a pixel; changing `fontSize`, `width`,
// `fieldHeight` or the labels moves the whole thing coherently instead of
// clipping against a constant that was tuned for one sentence.

/** Panel → field inset, and the panel's own bottom padding under the chips. */
const PAD = 4.7;
/** The panel sits a hair below the frame's centre line, as the reference's does. */
const PANEL_BIAS = 3.3;
/** Field text inset, and the line box, as multiples of the prompt's font size. */
const LINE_PAD_X = 1.12143;
const LINE_PAD_Y = 1.27857;
const LINE_HEIGHT = 1.21429;
const CARET_RATIO = 0.15714;
/** The chip row's own metrics, as multiples of the chip font size. */
const CHIP_HEIGHT = 2;
const CHIP_PAD_X = 0.93496;
const CHIP_GAP = 0.70732;
const CHIP_TOP = 0.54472;
/** The row starts a little inside the field's text inset. */
const CHIP_INSET = 0.72639;
/** The send button's corner, measured off the field's bottom-right. */
const SEND_RIGHT = 14.4;
const SEND_BOTTOM = 10.3;

// --- Measured timeline, in seconds -----------------------------------------

/** Reveal: a hairline at the panel's top edge that unrolls downward. */
const PANEL_GROW = 0.445;
/** The writing surface finishes first — 0.83 of the panel's own duration. */
const FIELD_GROW = 0.831;
/** The panel also widens as it unrolls — 0.93 of its width to all of it. */
const WIDEN = 0.2;
const WIDEN_FROM = 0.93;
/** Placeholder and send button, together, on a straight ramp. */
const FIELD_FADE = 0.3;
/** Each chip fades up over this, rising as it goes. */
const CHIP_DUR = 0.59;
const CHIP_RISE = 11.4;
/** Caret blink half-cycle, re-anchored on every keystroke. */
const BLINK = 0.474;
/** Press, then release, on the send button. */
const PRESS_DOWN = 0.067;
const PRESS_UP = 0.25;
const PRESS_SCALE = 0.87;

/**
 * The unroll. Nearly linear out of the gate, then a long settle — fitted to the
 * panel's measured height on twenty frames (rmse 2.5px on a 167px box).
 */
const REVEAL_EASE = Easing.bezier(0.3, 0, 0.35, 1);
/** The chips' rise. Fitted separately: it is a harder ease-out than the unroll. */
const CHIP_EASE = Easing.bezier(0.2, 0, 0.25, 1);
/** Real mouse deceleration — half the distance in the first eighth of the move. */
const CURSOR_EASE = Easing.bezier(0.16, 1, 0.3, 1);

// --- Pure helpers (unit-tested) --------------------------------------------

/** Eased 0→1 for a beat that starts at `at` and runs for `dur` seconds. */
function beat(
  t: number,
  at: number,
  dur: number,
  ease: (n: number) => number = REVEAL_EASE,
): number {
  if (dur <= 0) return t >= at ? 1 : 0;
  return interpolate(t, [at, at + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: ease,
  });
}

/**
 * Characters revealed at `t`, on an **ease-in-out sine** over `dur`.
 *
 * This is the one measurement that surprised: the reference does not type at a
 * constant rate. It accelerates in and decelerates out — 17 chars/sec over the
 * first word, 33 in the middle, and a visible settle on the last three. Fitting
 * a sine ease to the character count read off twenty-four frames lands within
 * **0.30 characters rms** across all 69, which no constant rate comes close to.
 *
 * It is also what makes the shot work: the camera rides this same curve, so the
 * push never jerks and never coasts.
 */
function typedCount(
  t: number,
  start: number,
  dur: number,
  total: number,
): number {
  if (t <= start) return 0;
  if (dur <= 0 || t >= start + dur) return total;
  const u = (t - start) / dur;
  return Math.min(total, Math.round((total * (1 - Math.cos(Math.PI * u))) / 2));
}

/** Continuous 0→1 of the same curve — what the camera and the field ride. */
function typedProgress(t: number, start: number, dur: number): number {
  if (t <= start) return 0;
  if (dur <= 0 || t >= start + dur) return 1;
  return (1 - Math.cos((Math.PI * (t - start)) / dur)) / 2;
}

/**
 * When the `count`-th character landed — the inverse of the sine ease.
 *
 * Needed because a caret does not blink on a wall clock, it blinks a fixed
 * interval after the last thing you typed. Anchoring the blink here is what
 * keeps it solid through the sentence and gets the two measured blinks after it
 * (off at 4.27s, on at 4.74s) for free.
 */
function keystrokeAt(
  count: number,
  start: number,
  dur: number,
  total: number,
): number {
  if (count <= 0 || total <= 0) return start;
  const p = Math.min(1, count / total);
  return start + (dur * Math.acos(1 - 2 * p)) / Math.PI;
}

/** Caret visibility: solid while typing, then blinking from the last keystroke. */
function caretOn(t: number, anchor: number, half: number): boolean {
  if (t < anchor) return false;
  if (half <= 0) return true;
  return Math.floor((t - anchor) / half) % 2 === 0;
}

export interface CameraShot {
  scale: number;
  x: number;
  y: number;
}

/**
 * The camera, as three hard states — there is no interpolation between them.
 *
 * Measured on the reference: the wide view is whole on one frame and fully
 * pushed in on the very next (1.958s → 1.975s), and the same again on the way
 * back out at 4.008s. Nothing in between, either time. Ramping it, even across
 * two frames, turns a cut into a zoom and the shot stops snapping.
 *
 * What *does* move is the middle state. It is not a fixed frame: it is pinned to
 * the caret, so as the sentence grows the camera tracks left with it. The pin is
 * on the **continuous** typing curve, not on the character count — which is why
 * the caret in the reference wobbles ±8px around its mark instead of sitting
 * dead still. Each keystroke jumps it forward; the camera slides underneath.
 *
 * Both marks are *fractions of the frame*, never pixel offsets, so a wider panel
 * or a bigger type size reframes rather than drifting off the edge.
 */
function cameraFor(
  t: number,
  o: {
    cutInAt: number;
    cutOutAt: number;
    zoomIn: number;
    zoomOut: number;
    caretX: number;
    caretY: number;
    sendX: number;
    sendY: number;
    focusX: number;
    focusY: number;
    outX: number;
    outY: number;
  },
): CameraShot {
  if (t >= o.cutOutAt) {
    return {
      scale: o.zoomOut,
      x: o.outX * REF_W - o.zoomOut * o.sendX,
      y: o.outY * REF_H - o.zoomOut * o.sendY,
    };
  }
  if (t >= o.cutInAt) {
    return {
      scale: o.zoomIn,
      x: o.focusX * REF_W - o.zoomIn * o.caretX,
      y: o.focusY * REF_H - o.zoomIn * o.caretY,
    };
  }
  return { scale: 1, x: 0, y: 0 };
}

/**
 * Greedy row-fill for the suggestion row.
 *
 * Four short labels are one row and that is the shot the reference shows, but a
 * component that only works for four short labels is one that breaks the first
 * time somebody writes a real one. Anything that will not fit wraps, the panel
 * grows by exactly the rows it gained, and the stagger keeps running in label
 * order across them.
 */
function packChipRows(
  widths: number[],
  available: number,
  gap: number,
): number[][] {
  const rows: number[][] = [];
  let row: number[] = [];
  let used = 0;
  widths.forEach((w, i) => {
    if (row.length > 0 && used + gap + w > available) {
      rows.push(row);
      row = [];
      used = 0;
    }
    used += row.length === 0 ? w : gap + w;
    row.push(i);
  });
  if (row.length > 0) rows.push(row);
  return rows;
}

export interface PromptSendLayout {
  panelTop: number;
  panelWidth: number;
  panelHeight: number;
  pad: number;
  fieldHeight: number;
  fieldRadius: number;
  /** Prompt line, relative to the panel's own box. */
  lineX: number;
  lineY: number;
  lineHeight: number;
  /** How much line fits before the field has to scroll under the caret. */
  lineMaxWidth: number;
  caretWidth: number;
  /** Suggestion row: `chipsX` from the panel's left, `chipsGap` below the field. */
  chipsX: number;
  chipsGap: number;
  chipHeight: number;
  chipPadX: number;
  chipGap: number;
  chipRows: number[][];
  sendSize: number;
  sendRight: number;
  sendBottom: number;
}

/**
 * The whole geometry, from four numbers and the measured label widths.
 *
 * Every offset the recording gave up is in here either as a fixed inset or as a
 * ratio of a font size, so the defaults reproduce the reference exactly and any
 * other content still lands somewhere sensible. The panel's height is *derived*
 * — padding, field, the gap, however many chip rows there turned out to be — so
 * it hugs its content rather than being a constant that fits one sentence.
 */
function layoutFor(o: {
  width: number;
  fieldHeight: number;
  fontSize: number;
  chipFontSize: number;
  radius: number;
  sendSize: number;
  chipWidths: number[];
}): PromptSendLayout {
  const lineX = PAD + o.fontSize * LINE_PAD_X;
  const chipHeight = o.chipFontSize * CHIP_HEIGHT;
  const chipGap = o.chipFontSize * CHIP_GAP;
  const chipsX = PAD + (lineX - PAD) * CHIP_INSET;
  const chipRows = packChipRows(o.chipWidths, o.width - chipsX * 2, chipGap);
  const chipsGap = o.chipFontSize * CHIP_TOP;

  // The line only yields room to the send button when the two actually share a
  // row. On the reference's 121px field they do not — the button sits well below
  // the text — so the full width is the line's. Shrink the field to a single-row
  // control and the line starts scrolling before it can run under the button.
  const lineBottom = PAD + o.fontSize * LINE_PAD_Y + o.fontSize * LINE_HEIGHT;
  const sendTop = PAD + o.fieldHeight - SEND_BOTTOM - o.sendSize;
  const sendGutter =
    lineBottom > sendTop ? o.sendSize + SEND_RIGHT + o.fontSize * 0.5 : 0;

  // No chips → the panel simply hugs the field. With chips it opens up by the
  // gap, the rows it needs, and its own bottom padding.
  const below =
    chipRows.length === 0
      ? PAD
      : chipsGap +
        chipRows.length * chipHeight +
        (chipRows.length - 1) * chipGap +
        PAD * 2;
  const panelHeight = PAD + o.fieldHeight + below;

  return {
    panelTop: (REF_H - panelHeight) / 2 + PANEL_BIAS,
    panelWidth: o.width,
    panelHeight,
    pad: PAD,
    fieldHeight: o.fieldHeight,
    fieldRadius: Math.max(0, o.radius - 2),
    lineX,
    lineY: PAD + o.fontSize * LINE_PAD_Y,
    lineHeight: o.fontSize * LINE_HEIGHT,
    lineMaxWidth: Math.max(0, o.width - lineX * 2 - sendGutter),
    caretWidth: o.fontSize * CARET_RATIO,
    chipsX,
    chipsGap,
    chipHeight,
    chipPadX: o.chipFontSize * CHIP_PAD_X,
    chipGap,
    chipRows,
    sendSize: o.sendSize,
    sendRight: SEND_RIGHT,
    sendBottom: SEND_BOTTOM,
  };
}

/** Accepts an array or the comma-separated string the customizer passes. */
function chipList(chips?: string[] | string): string[] {
  const list = typeof chips === "string" ? chips.split(",") : (chips ?? []);
  return list.map((c) => c.trim()).filter(Boolean);
}

// One measuring context, reused. `measureText` runs once per label per frame,
// and allocating a canvas each time is the sort of thing that only shows up
// when somebody renders four minutes of it.
let measureCtx: CanvasRenderingContext2D | null | undefined;

/** Advance width of `text`, measured on the face we actually draw. */
function measureWidth(
  text: string,
  size: number,
  family: string = SANS,
  weight = 400,
): number {
  if (!text) return 0;
  if (typeof document === "undefined") return text.length * size * 0.5;
  if (measureCtx === undefined) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) return text.length * size * 0.5;
  measureCtx.font = `${weight} ${size}px ${family}, system-ui, sans-serif`;
  return measureCtx.measureText(text).width;
}

// --- Cursor ----------------------------------------------------------------

/**
 * The pointing hand, at the size the recording caught it: 18×27, hotspot on the
 * fingertip. Drawn in **stage** space, outside the camera — a pointer is a
 * property of the screen, not of the thing on it, so it must not scale when the
 * camera cuts in.
 */
function HandCursor({
  x,
  y,
  size,
  fill,
  stroke,
}: {
  x: number;
  y: number;
  size: number;
  fill: string;
  stroke: string;
}) {
  return (
    <svg
      viewBox="0 0 18 27"
      width={size * (18 / 27)}
      height={size}
      style={{
        position: "absolute",
        // The hotspot is the fingertip, which sits 6.2 of 18 across the glyph
        // and 1 of 27 down it — not the box's corner.
        left: x - size * (6.2 / 27),
        top: y - size * (1 / 27),
        display: "block",
        filter: "drop-shadow(0 1px 1.5px rgba(0,0,0,0.28))",
      }}
    >
      <title>Pointer</title>
      <path
        d="M4.1 15.6V3.1a2.1 2.1 0 0 1 4.2 0v7.6h.6l.3-1.5a1.7 1.7 0 0 1 3.4.3v1.5l.4-.5a1.7 1.7 0 0 1 3 1.1v1.1l.4-.2a1.6 1.6 0 0 1 1.9 1.6v4.6c0 3.6-2.4 6.3-6.1 6.3H9.6c-2.6 0-4-1-5.2-2.7l-3.2-4.6a1.7 1.7 0 0 1 2.5-2.2l.4.4Z"
        fill={fill}
        stroke={stroke}
        strokeWidth={1.1}
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** The send glyph: an up arrow, drawn to fill its disc the way the reference does. */
function SendArrow({ size, color }: { size: number; color: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      stroke={color}
      strokeWidth={2.2}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ display: "block" }}
    >
      <title>Send</title>
      <path d="M12 19V5M5.5 11.5 12 5l6.5 6.5" />
    </svg>
  );
}

// --- Props -----------------------------------------------------------------

export interface PromptSendProps {
  /** The brief that types itself. Any length — the field scrolls under the caret. */
  text?: string;
  /** Shown until the first character lands. */
  placeholder?: string;
  /**
   * The suggestion row under the field. Pass an array, or the comma-separated
   * string the customizer sends. They wrap, and the panel grows to hold them;
   * pass `[]` for a bare field.
   */
  chips?: string[] | string;
  /** Replaces the up-arrow in the send button. */
  sendIcon?: ReactNode;

  // --- Size. Every default is the recording's own measurement. ---
  /** Panel width, in stage px (the stage is 890×486, scaled to the composition). */
  width?: number;
  /** Height of the writing surface. The panel's height follows from it. */
  fieldHeight?: number;
  /** Prompt type size. The line box, caret and field padding all follow from it. */
  fontSize?: number;
  /** Chip label size. Chip height, padding and the row gap all follow from it. */
  chipFontSize?: number;
  /** Panel corner radius. The field's is this less 2, as the reference's is. */
  radius?: number;
  /** Diameter of the send button. */
  sendSize?: number;
  /** Overrides the loaded Inter — only useful if you have already loaded a face. */
  fontFamily?: string;

  // --- Timing, in seconds. ---
  /** When the panel starts to unroll, and how long the unroll takes. */
  revealAt?: number;
  revealDuration?: number;
  /** When the placeholder and the send button fade up. */
  fieldAt?: number;
  /** When the caret arrives (whole — it does not fade). */
  caretAt?: number;
  /** When the first chip starts, and the gap between them. */
  chipsAt?: number;
  chipStagger?: number;
  /** When typing starts, and how long the whole sentence takes. */
  typeStart?: number;
  typeDuration?: number;
  /** When the view cuts in to the caret, and back out to the button. */
  cutInAt?: number;
  cutOutAt?: number;
  /** How far each cut pushes. Both are measured off the reference. */
  zoomIn?: number;
  zoomOut?: number;
  /** Where the caret sits in frame while the camera rides it. */
  focusX?: number;
  focusY?: number;
  /** Where the send button sits in frame after the second cut. */
  outX?: number;
  outY?: number;
  /** When the pointer starts its approach, how long it takes, and when it clicks. */
  cursorAt?: number;
  cursorDuration?: number;
  clickAt?: number;
  /** Show the pointer at all. Off drops the click and the send bloom with it. */
  cursor?: boolean;

  // --- Paint. ---
  /** The wash behind the panel and the send bloom. Defaults to `theme.primary`. */
  accentColor?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  speed?: number;
}

// --- Main composition ------------------------------------------------------

/**
 * A prompt composer that unrolls from a hairline, writes a brief into itself
 * while the camera rides the caret, then cuts back out and gets sent.
 *
 * ## Four things were measured, and they are the component
 *
 * **The unroll.** It does not fade in and it does not scale up from nothing. A
 * 2px white line appears at the panel's top edge and the box grows *downward*
 * out of it — top edge pinned, bottom edge travelling its full height in 445ms —
 * while the width goes from 0.93 to 1. The writing surface and the chip strip
 * are two separate heights on the same curve with different durations, which is
 * why the strip surfaces from under the field late rather than being there from
 * the first frame.
 *
 * **The typing is eased.** 17 chars/sec on the first word, 33 in the middle, and
 * a visible settle on the last three. An ease-in-out sine over the character
 * count fits all 69 of the reference's to within 0.30 characters rms; no
 * constant rate is close.
 *
 * **The camera cuts, and then it rides.** 2.327× in a single frame, landing with
 * the caret 57% across the frame, then tracking left with the sentence — pinned
 * to the *continuous* typing curve, so the caret wobbles ±8px about its mark as
 * each character jumps ahead of the slide. Then it cuts again, out to 1.44×,
 * centred on the send button, which is where the pointer is already heading.
 *
 * **The pointer is a real mouse.** It enters the bottom-right corner and its
 * distance to the button halves every 44ms — an exponential approach, not a
 * constant glide. It is drawn outside the camera because a pointer belongs to
 * the screen, not to the scene, and must not grow when the shot pushes in.
 *
 * ## Nothing here is a constant tuned to one sentence
 *
 * Every offset above is either a fixed inset or a ratio of a font size, and
 * `layoutFor` turns four numbers — `width`, `fieldHeight`, `fontSize`,
 * `chipFontSize` — into the whole geometry. Longer copy scrolls the field under
 * the caret instead of running past its edge; more chips wrap and the panel
 * grows by exactly the rows they needed; no chips at all and it hugs the field.
 * Both camera marks are fractions of the frame, so a wider panel reframes rather
 * than drifting off it.
 *
 * ## What is not measured
 *
 * The colours and the wording. The reference is a specific product with a
 * specific blue; none of that belongs in a component that ships to strangers and
 * lands next to somebody else's `Input` (design-system rule 5). The paint is the
 * shadcn token set, the field takes its surface from the `Input` primitive's own
 * style context so the two cannot drift, the wash is layered from `accentColor`
 * (`theme.primary` by default), and every string is a prop.
 */
function PromptSendScene({
  text = "Add a text reveal, a soft blur transition, and a gradient background",
  placeholder = "Describe the scene you want…",
  chips = "Add a text reveal, Try a blur transition, Pick a background, Assemble a scene",
  sendIcon,
  width = 636.2,
  fieldHeight = 121.2,
  fontSize = 14,
  chipFontSize = 12.3,
  radius = 22,
  sendSize = 27.4,
  fontFamily,
  revealAt = 0.025,
  revealDuration = PANEL_GROW,
  fieldAt = 0.417,
  caretAt = 0.742,
  chipsAt = 0.545,
  chipStagger = 0.1,
  typeStart = 0.915,
  typeDuration = 3.025,
  cutInAt = 1.975,
  cutOutAt = 4.008,
  zoomIn = 2.327,
  zoomOut = 1.44,
  focusX = 0.573,
  focusY = 0.4881,
  outX = 0.5305,
  outY = 0.5261,
  cursorAt = 4.042,
  cursorDuration = 0.42,
  clickAt = 4.658,
  cursor = true,
  accentColor,
  theme,
  mode,
  speed = 1,
}: PromptSendProps) {
  const frame = useCurrentFrame();
  const { width: compWidth, height: compHeight, fps } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;
  const ui = inputStyleContext(t);
  const accent = accentColor ?? t.primary;

  const now = (frame * speed) / fps;
  const stageScale = Math.min(compWidth / REF_W, compHeight / REF_H);

  // --- layout -------------------------------------------------------------
  const labels = chipList(chips);
  const L = layoutFor({
    width,
    fieldHeight,
    fontSize,
    chipFontSize,
    radius,
    sendSize,
    chipWidths: labels.map(
      (c) =>
        measureWidth(c, chipFontSize, face) + chipFontSize * CHIP_PAD_X * 2 + 2,
    ),
  });

  // --- reveal -------------------------------------------------------------
  const panelH = L.panelHeight * beat(now, revealAt, revealDuration);
  const fieldH =
    L.fieldHeight * beat(now, revealAt, revealDuration * FIELD_GROW);
  const panelW =
    L.panelWidth * (WIDEN_FROM + (1 - WIDEN_FROM) * beat(now, revealAt, WIDEN));
  const panelLeft = (REF_W - panelW) / 2;
  // The chips hang off the field's bottom edge, so they ride its growth and are
  // already in place by the time the first one fades up.
  const fieldBottom = L.pad + fieldH;

  const fieldIn = interpolate(now, [fieldAt, fieldAt + FIELD_FADE], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- typing -------------------------------------------------------------
  const count = typedCount(now, typeStart, typeDuration, text.length);
  const typed = text.slice(0, count);
  const progress = typedProgress(now, typeStart, typeDuration);
  const fullWidth = measureWidth(text, fontSize, face);

  // The line rides the *continuous* curve, so a sentence longer than the field
  // scrolls under the caret the way a real single-line input does — and the
  // caret, quantised to whole characters, hops either side of the mark rather
  // than the whole line jerking once per keystroke.
  const advance = fullWidth * progress;
  const room = Math.max(0, L.lineMaxWidth - L.caretWidth);
  const scrolled = Math.max(0, advance - room);
  const caretSceneX = panelLeft + L.lineX + Math.min(advance, room);

  const caretAnchor =
    count === 0
      ? caretAt
      : // Clamped to `now`: the count is rounded, so the inverse of the ease can
        // put the "last keystroke" a few milliseconds in the future — and a
        // blink anchored in the future reads as a caret that is off while you
        // are typing.
        Math.min(
          now,
          Math.max(
            caretAt,
            // `count - 0.5` because the count is *rounded*: the character
            // appears when the eased value crosses the half, and that crossing
            // is the keystroke the caret's blink hangs off.
            keystrokeAt(count - 0.5, typeStart, typeDuration, text.length),
          ),
        );
  const caretLit = now >= caretAt && caretOn(now, caretAnchor, BLINK);

  // --- camera -------------------------------------------------------------
  const sendX = panelLeft + panelW - L.pad - L.sendRight - L.sendSize / 2;
  const sendY =
    L.panelTop + L.pad + L.fieldHeight - L.sendBottom - L.sendSize / 2;
  const shot = cameraFor(now, {
    cutInAt,
    cutOutAt,
    zoomIn,
    zoomOut,
    caretX: caretSceneX,
    caretY: L.panelTop + L.lineY + L.lineHeight / 2,
    sendX,
    sendY,
    focusX,
    focusY,
    outX,
    outY,
  });

  // --- pointer ------------------------------------------------------------
  const approach = interpolate(
    now,
    [cursorAt, cursorAt + cursorDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: CURSOR_EASE,
    },
  );
  // It parks just up and right of dead centre on the button, which is where a
  // hand cursor actually lands when you aim at a target this size.
  const sendScreenX = shot.x + shot.scale * sendX + sendSize * 0.098;
  const sendScreenY = shot.y + shot.scale * sendY - sendSize * 0.091;
  const cursorX = interpolate(approach, [0, 1], [REF_W * 0.86, sendScreenX]);
  const cursorY = interpolate(approach, [0, 1], [REF_H * 1.02, sendScreenY]);

  // --- press and send -----------------------------------------------------
  const press = !cursor
    ? 0
    : now < clickAt
      ? 0
      : now < clickAt + PRESS_DOWN
        ? (now - clickAt) / PRESS_DOWN
        : Math.max(0, 1 - (now - clickAt - PRESS_DOWN) / PRESS_UP);
  const pressScale = 1 - (1 - PRESS_SCALE) * press;
  // The send bloom. It opens 220ms after the press — the reference's does — and
  // sweeps across the field rather than sitting still. The recording ends 140ms
  // into it, so the opening is measured and the rest is ours.
  const glow = !cursor
    ? 0
    : beat(now, clickAt + 0.22, 0.3, Easing.out(Easing.quad));
  const sweep = beat(now, clickAt + 0.22, 1.1, Easing.out(Easing.quad));

  // --- paint --------------------------------------------------------------
  // A hairline is specified at a 40px control; this panel is much taller, so the
  // token is walked toward the background through the system's own mix rather
  // than by picking a lighter grey (design-system rule 3b).
  const hairline = mixOklch(ui.idleBorder, t.background, 0.1);
  // A transparent page asks for no page: the wash is the page's, so it goes too.
  const bare = parseColor(t.background).alpha === 0;
  const surface = withAlpha(t.card, 0.94);
  const glassy = withAlpha(t.card, 0.52);
  const sendIdle = mixOklch(t.foreground, t.card, 0.55);
  const armed = count > 0;

  const isRendering = getRemotionEnvironment().isRendering;
  const willChange = isRendering ? undefined : ("transform" as const);

  return (
    <AbsoluteFill showInTimeline={false} style={{ background: t.background }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: REF_W,
          height: REF_H,
          transform: `translate(-50%, -50%) scale(${stageScale})`,
          overflow: "hidden",
        }}
      >
        {/* The camera. A plain static transform per shot — never interpolated
            between them, so there is no frame on which a cut is halfway. */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${shot.x}px, ${shot.y}px) scale(${shot.scale})`,
            transformOrigin: "0 0",
            willChange,
          }}
        >
          {/* The backdrop rides *inside* the camera, because on the reference it
              does — the wash grows with everything else when the shot pushes in.
              It is drawn on an oversized box (and positioned in px, not %, so
              the maths stays the stage's) because the second cut frames past the
              stage's right edge and a wash that stopped there would show a seam.

              The shape is the reference's: a cool field falling from the top
              right, a bright patch left of centre, a warm corner under it. The
              paint is not — it is layered as alpha over the installer's own
              `background` and `accentColor` (design-system rule 5). Alpha, not
              `mixOklch`: hue interpolation from a near-neutral page colour to
              blue takes the short way round, through green. */}
          {!bare && (
            <div
              style={{
                position: "absolute",
                left: -OX,
                top: -OY,
                width: REF_W * BLEED,
                height: REF_H * BLEED,
                background: t.background,
                backgroundImage: [
                  `radial-gradient(${0.96 * REF_W}px ${0.8 * REF_H}px at ${OX + 0.06 * REF_W}px ${OY + 0.98 * REF_H}px, ${withAlpha(t.background, 0.9)} 0%, transparent 62%)`,
                  `radial-gradient(${0.74 * REF_W}px ${0.62 * REF_H}px at ${OX + 0.1 * REF_W}px ${OY + 0.46 * REF_H}px, ${withAlpha(t.card, 0.42)} 0%, transparent 66%)`,
                  `linear-gradient(215deg, ${withAlpha(accent, 0.5)} 0%, ${withAlpha(accent, 0.28)} 52%, ${withAlpha(accent, 0.14)} 100%)`,
                ].join(","),
              }}
            />
          )}

          {/* ---- The glass panel */}
          <div
            style={{
              position: "absolute",
              left: panelLeft,
              top: L.panelTop,
              width: panelW,
              height: panelH,
              borderRadius: radius,
              background: glassy,
              // The hairline is an inset shadow, not a border: a border is
              // layout, and every measured offset below is from the panel's own
              // box. One pixel of border would push all of them one pixel in.
              boxShadow: `inset 0 0 0 1px ${withAlpha(t.card, 0.6)}, 0 12px 32px ${withAlpha(t.foreground, 0.05)}`,
              overflow: "hidden",
            }}
          >
            {/* ---- The writing surface */}
            <div
              style={{
                position: "absolute",
                left: L.pad,
                top: L.pad,
                width: Math.max(0, panelW - L.pad * 2),
                height: fieldH,
                borderRadius: L.fieldRadius,
                background: surface,
                boxShadow: `0 6px 18px ${withAlpha(t.foreground, 0.05)}`,
                overflow: "hidden",
              }}
            >
              {/* The send bloom: what the click buys you. Inside the field so it
                  is clipped by its radius, the way the reference's is. */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  opacity: glow,
                  background: `radial-gradient(80% 170% at ${16 + sweep * 66}% 96%, ${withAlpha(accent, 0.55)} 0%, transparent 66%)`,
                }}
              />

              {/* The prompt line, translated left once the sentence outgrows the
                  field. Caret between the value and the placeholder, which is
                  where the reference puts it — the placeholder starts one caret
                  width right of the text origin, not on it. */}
              <div
                style={{
                  position: "absolute",
                  left: L.lineX - L.pad - scrolled,
                  top: L.lineY - L.pad,
                  display: "flex",
                  alignItems: "center",
                  height: L.lineHeight,
                  fontFamily: face,
                  fontWeight: 400,
                  fontSize,
                  lineHeight: `${L.lineHeight}px`,
                  color: t.foreground,
                  whiteSpace: "pre",
                  textRendering: "geometricPrecision",
                }}
              >
                {typed}
                <span
                  style={{
                    display: "inline-block",
                    width: L.caretWidth,
                    height: L.lineHeight,
                    background: t.foreground,
                    opacity: caretLit ? 1 : 0,
                    flexShrink: 0,
                  }}
                />
                {count === 0 ? (
                  <span style={{ color: ui.mutedForeground, opacity: fieldIn }}>
                    {placeholder}
                  </span>
                ) : null}
              </div>

              {/* ---- Send */}
              <div
                style={{
                  position: "absolute",
                  right: L.sendRight,
                  bottom: L.sendBottom,
                  width: L.sendSize,
                  height: L.sendSize,
                  borderRadius: L.sendSize / 2,
                  background: armed ? t.foreground : sendIdle,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  opacity: fieldIn,
                  transform: `scale(${pressScale})`,
                  willChange,
                }}
              >
                {sendIcon ?? (
                  <SendArrow size={L.sendSize * 0.56} color={t.card} />
                )}
              </div>
            </div>

            {/* ---- Suggestions */}
            <div
              style={{
                position: "absolute",
                left: L.chipsX,
                top: fieldBottom + L.chipsGap,
                right: L.chipsX,
                display: "flex",
                flexDirection: "column",
                gap: L.chipGap,
              }}
            >
              {L.chipRows.map((row) => (
                <div
                  key={row.join("-")}
                  style={{ display: "flex", gap: L.chipGap }}
                >
                  {row.map((i) => {
                    const p = beat(
                      now,
                      chipsAt + i * chipStagger,
                      CHIP_DUR,
                      CHIP_EASE,
                    );
                    return (
                      <Item key={labels[i]} index={i}>
                        <div
                          style={{
                            boxSizing: "border-box",
                            height: L.chipHeight,
                            padding: `0 ${L.chipPadX}px`,
                            borderRadius: L.chipHeight / 2,
                            background: t.card,
                            border: `1px solid ${hairline}`,
                            color: t.foreground,
                            fontFamily: face,
                            fontWeight: 400,
                            fontSize: chipFontSize,
                            // The label rides low in the pill on the reference,
                            // which is what stops a small label in a round pill
                            // reading as though it were floating.
                            paddingTop: chipFontSize * 0.17073,
                            lineHeight: `${L.chipHeight - 4}px`,
                            whiteSpace: "nowrap",
                            textRendering: "geometricPrecision",
                            opacity: p,
                            transform: `translateY(${(1 - p) * CHIP_RISE}px)`,
                            willChange,
                          }}
                        >
                          {labels[i]}
                        </div>
                      </Item>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        </div>

        {cursor && approach > 0 ? (
          <HandCursor
            x={cursorX}
            y={cursorY}
            size={27}
            fill={t.card}
            stroke={mixOklch(t.foreground, t.card, 0.2)}
          />
        ) : null}
      </div>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one chip at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function PromptSendPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}

/** Whether every box that clips `el`, up to `root`, leaves all of it showing. */
function PromptSendWhole(el: Element, root: Element): boolean {
  const r = el.getBoundingClientRect();
  for (let a = el.parentElement; a; a = a === root ? null : a.parentElement) {
    if (getComputedStyle(a).overflow === "visible") continue;
    const c = a.getBoundingClientRect();
    if (
      r.left < c.left - 1 ||
      r.top < c.top - 1 ||
      r.right > c.right + 1 ||
      r.bottom > c.bottom + 1
    )
      return false;
  }
  return true;
}
type PromptSendChipValues = {
  readonly label?: string;
};

type PromptSendChipProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  PromptSendChipValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this chip as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: PromptSendChipState) => void;
  };

/** What Studio is doing to one chip right now, which the stage applies to its node. */
type PromptSendChipState = {
  values: PromptSendChipValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const PromptSendChipSchema = {
  ...Interactive.baseSchema,
  label: { type: "text-content", default: "", description: "Label" },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One chip: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the chip is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const PromptSendChipInner = forwardRef<
  Element,
  PromptSendChipProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      label,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it or it paints past its own box; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { label },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? PromptSendPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const n = el.getBoundingClientRect();
      if (
        PromptSendWhole(el, root) &&
        b[0] >= n.left - 1 &&
        b[1] >= n.top - 1 &&
        b[2] <= n.right + 1 &&
        b[3] <= n.bottom + 1
      ) {
        box.style.display = "none";
        target.current = el;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Chip"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const PromptSendChip = Interactive.withSchema({
  Component: PromptSendChipInner,
  componentName: "<PromptSendChip>",
  schema: PromptSendChipSchema,
  supportsEffects: false,
});

type PromptSendStageProps = InteractiveBaseProps &
  Omit<ComponentProps<typeof PromptSendScene>, "chips"> & {
    readonly children?: ReactNode;
  };

/**
 * What a scene prop falls back to when Studio does not pass it, reset included.
 * The chips' own lists are here only for the scene's parameter defaults;
 * the stage always passes the ones its children build.
 */
const PromptSendDefaults = {
  text: "Add a text reveal, a soft blur transition, and a gradient background",
  placeholder: "Describe the scene you want…",
  chips:
    "Add a text reveal, Try a blur transition, Pick a background, Assemble a scene",
  width: 636.2,
  fieldHeight: 121.2,
  fontSize: 14,
  chipFontSize: 12.3,
  radius: 22,
  typeStart: 0.915,
  typeDuration: 3.025,
  chipsAt: 0.545,
  chipStagger: 0.1,
  cutInAt: 1.975,
  cutOutAt: 4.008,
  zoomIn: 2.327,
  zoomOut: 1.44,
  focusX: 0.573,
  focusY: 0.4881,
  clickAt: 4.658,
  cursor: true,
  accentColor: "#3072db",
  mode: "light",
  speed: 1,
  theme: { background: "transparent" },
} satisfies Partial<PromptSendStageProps> &
  Partial<Pick<ComponentProps<typeof PromptSendScene>, "chips">>;

const PromptSendStageSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default:
      "Add a text reveal, a soft blur transition, and a gradient background",
    description: "Prompt",
  },
  placeholder: {
    type: "text-content",
    default: "Describe the scene you want…",
    description: "Placeholder",
  },
  accentColor: {
    type: "color",
    default: "#3072db",
    description: "Accent",
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Mode",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * A value as the scene's list will read it back: each separator it would split
 * on becomes a character that looks the same and does not split, so "Hello,
 * world" stays one chip and the ones after it keep their outlines.
 */
function PromptSendClean(v: string | undefined, seps: string): string {
  const look: Record<string, string> = {
    ",": "\u201A",
    "|": "\u2223",
    ";": "\u037E",
    ">": "\u203A",
  };
  let out = v ?? "";
  for (const c of seps.split(" ").join(""))
    out = out.split(c).join(look[c] ?? " ");
  return out;
}

/** The scene's props, from its chips' values in order. */
const PromptSendFromItems = (o: readonly PromptSendChipValues[]) => ({
  chips: o.map((x) => PromptSendClean(x.label, ", ")).join(", "),
});

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function PromptSendFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function PromptSendHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its chips as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const PromptSendStageInner = forwardRef<
  HTMLDivElement,
  PromptSendStageProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per chip on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every chip the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<PromptSendChipProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const rest = { ...PromptSendDefaults, ...props };
    // What Studio is doing to each chip that the file may not have yet.
    const [live, setLive] = useState<Record<number, PromptSendChipState>>({});
    const report = (j: number, state: PromptSendChipState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all
      .map((_, j) => j)
      .filter((j) =>
        ((x: PromptSendChipValues) => Boolean(x.label?.trim()))(
          merged[j] as PromptSendChipValues,
        ),
      );
    const built = PromptSendFromItems(
      kept.map((j) => merged[j] as PromptSendChipValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
          ...(m.label === undefined ? null : { children: m.label }),
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...PromptSendFromItems(
        all
          .filter((o) =>
            ((x: PromptSendChipValues) => Boolean(x.label?.trim()))(o.props),
          )
          .map((o) => o.props),
      ),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Prompt Send"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <PromptSendFade>
            <PromptSendHosted host={host}>
              <PromptSendScene key={key} {...rest} {...built} />
            </PromptSendHosted>
          </PromptSendFade>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: PromptSendChipState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

const PromptSendStage = Interactive.withSchema({
  Component: PromptSendStageInner,
  componentName: "<PromptSendStage>",
  schema: PromptSendStageSchema,
  supportsEffects: false,
});

/**
